(() => {
 'use strict';
 const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], esc=MGTU_escape;
 const modal=$('#modal'), modalContent=$('#modalContent');
 let data={programs:[],facts:[]},content=MGTU_content(),level='Бакалавриат',limit=6;
 let compared=MGTU_read('mgtu-compared',[]); if(!Array.isArray(compared)) compared=[];
 let checked=MGTU_read('mgtu-checklist',[]); if(!Array.isArray(checked)) checked=[];
 let toastTimer;
 const motion=true;
 document.documentElement.classList.add('js-motion');
 function toast(message){$('#toast').className='toast visible';$('#toast').textContent=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
 const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('pending');observer.unobserve(e.target);}}),{threshold:.08});
 $$('.reveal').forEach(el=>{el.classList.add('pending');observer.observe(el);});
 document.addEventListener('pointermove',e=>{if(!motion||e.pointerType==='touch')return;const target=e.target.closest('.spotlight');if(target){const r=target.getBoundingClientRect();target.style.setProperty('--x',e.clientX-r.left+'px');target.style.setProperty('--y',e.clientY-r.top+'px');}});
 const art=$('.hero-art'); art.addEventListener('pointermove',e=>{if(!motion||e.pointerType==='touch')return;const r=art.getBoundingClientRect();$('.photo-main').style.transform=`perspective(900px) rotateY(${(e.clientX-r.left-r.width/2)/30}deg) rotateX(${-(e.clientY-r.top-r.height/2)/35}deg) rotate(5deg)`;});art.addEventListener('pointerleave',()=>$('.photo-main').style.transform='');
 window.addEventListener('scroll',()=>$('.header').classList.toggle('scrolled',scrollY>30),{passive:true});
 $('#menuToggle').addEventListener('click',()=>{const open=$('.header nav').classList.toggle('open');$('#menuToggle').setAttribute('aria-expanded',String(open));$('#menuToggle').setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');});
 $$('.header nav a').forEach(a=>a.addEventListener('click',()=>{$('.header nav').classList.remove('open');$('#menuToggle').setAttribute('aria-expanded','false');}));
 function applyContent(){content=MGTU_content();const root=document.documentElement;root.style.setProperty('--accent',content.accent);root.style.setProperty('--violet',content.secondary);root.style.setProperty('--ink',content.background);root.style.setProperty('--font',`"${String(content.font).replace(/[";<>]/g,'')}",Arial,sans-serif`);
 const lines=content.title.split('\n');$('#heroTitle').innerHTML=lines.map((l,i)=>i===lines.length-1?`<em>${esc(l)}</em>`:esc(l)+'<br>').join('');
 $('#heroDescription').textContent=content.description;$('#eventDate').textContent=content.date;$('#eventPlace').textContent=content.place;
 $('#contactPhone').textContent=content.phone;$('#contactPhone').href='tel:'+content.phone.replace(/[^+\d]/g,'').replace(/^8(?=\d{10}$)/,'+7');$('#contactEmail').textContent=content.email;$('#contactEmail').href='mailto:'+content.email;
 Object.entries(content.sections).forEach(([key,show])=>{const selector={about:'.about',discover:'.discover',programs:'.programs-section',plan:'.plan-section',resources:'.resources-section',faq:'.faq-section'}[key];if(selector)$(selector).hidden=!show;});
 Object.entries(content.texts||{}).forEach(([key,value])=>{const selectors={aboutTitle:'.about h2',aboutDescription:'.about .section-heading>p',discoverTitle:'.discover h2',discoverDescription:'.discover-sticky>p',programsTitle:'.programs-section h2',programsDescription:'.programs-section .section-heading>p',planTitle:'.plan-copy h2',planDescription:'.plan-copy>p',resourcesTitle:'.resources-section h2',faqTitle:'.faq-section h2',finalTitle:'.final-cta h2'};const node=selectors[key]&&$(selectors[key]);if(node){if(['aboutTitle','programsTitle','resourcesTitle'].includes(key))node.textContent=String(value).replace(/\s+/g,' ').trim();else node.innerHTML=esc(value).replace(/\n/g,'<br>');}});
 renderChecklist();if(data.programs.length)renderPrograms();}
 applyContent();window.addEventListener('storage',e=>{if(e.key==='mgtu-content')applyContent();});
 function programs(){return data.programs.map(p=>({...p,...content.programs[p.id]})).filter(p=>p.visible!==false);}
 const symbol=faculty=>/аграр/i.test(faculty)?'✳':/информа/i.test(faculty)?'⌘':/эконом/i.test(faculty)?'◉':/лечеб|стомат|фарма|педиат/i.test(faculty)?'✚':/экол/i.test(faculty)?'❋':'◈';
 const priority=['pi','ib','eco_eco','str','ur','agro'];
 function renderPrograms(){
  const query=$('#programSearch').value.trim().toLocaleLowerCase('ru');const faculty=$('#facultyFilter').value;
  const list=programs().filter(p=>p.level===level&&(!faculty||p.faculty===faculty)&&(!query||(p.name+' '+p.faculty).toLocaleLowerCase('ru').includes(query))).sort((a,b)=>{let ia=priority.indexOf(a.id),ib=priority.indexOf(b.id);return (ia<0?99:ia)-(ib<0?99:ib);});
  $('#resultCount').textContent=level==='СПО'?'':`${list.length} ${plural(list.length,'направление','направления','направлений')}`;
  if(level==='СПО'){$('#programGrid').innerHTML='<div class="empty-state"><h3>Твой старт — в колледже</h3><p>Информация о поступлении в политехнический колледж МГТУ — в памятке абитуриента.</p><a class="button dark-button" target="_blank" rel="noopener" href="https://2504.mkgtu.ru/upload/pam_abit_2026_kolledg.pdf">Открыть памятку </a></div>';}
  else $('#programGrid').innerHTML=list.slice(0,limit).map(p=>`<article class="program-card spotlight" data-theme="${MGTU_theme(p)}"><div class="program-top"><span>${esc(p.level)}${p.document?.match(/\d{2}\.\d{2}\.\d{2}/)?' · '+p.document.match(/\d{2}\.\d{2}\.\d{2}/)[0]:''}<small class="program-theme">${esc(MGTU_PALETTES[MGTU_theme(p)].name)}</small></span><span class="program-symbol" aria-hidden="true">${symbol(p.faculty)}</span></div><h3>${esc(p.name)}</h3><p class="faculty">${esc(p.faculty)}</p><div class="program-actions"><button data-detail="${esc(p.id)}">О направлении </button><button class="compare-toggle ${compared.includes(p.id)?'selected':''}" aria-pressed="${compared.includes(p.id)}" data-compare="${esc(p.id)}" aria-label="${compared.includes(p.id)?'Убрать из сравнения:':'Сравнить:'} ${esc(p.name)}">${compared.includes(p.id)?'В сравнении':'Сравнить'}</button></div></article>`).join('')||'<div class="empty-state"><h3>Пока ничего не нашлось</h3><p>Попробуй другое слово или выбери все факультеты.</p><button class="button outline" id="resetSearch">Сбросить поиск</button></div>';
  $('#showMore').hidden=limit>=list.length||level==='СПО';syncCompare();
 }
 function plural(n,one,few,many){return n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many;}
 function fillFaculties(){const all=[...new Set(programs().filter(p=>p.level===level).map(p=>p.faculty))];$('#facultyFilter').innerHTML='<option value="">Все факультеты</option>'+all.map(f=>`<option>${esc(f)}</option>`).join('');$('#facultyFilter').disabled=level==='СПО';}
 $('#programSearch').addEventListener('input',()=>{limit=6;renderPrograms();});$('#facultyFilter').addEventListener('change',()=>{limit=6;renderPrograms();});
 $('#levelTabs').addEventListener('click',e=>{const b=e.target.closest('[data-level]');if(!b)return;level=b.dataset.level;limit=6;$$('#levelTabs button').forEach(el=>{const active=el===b;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});fillFaculties();renderPrograms();});
 $('#showMore').addEventListener('click',()=>{limit+=6;renderPrograms();});
 document.addEventListener('click',e=>{const detail=e.target.closest('[data-detail]'),compare=e.target.closest('[data-compare]'),register=e.target.closest('[data-register]');if(detail)showProgram(detail.dataset.detail);if(compare)toggleCompare(compare.dataset.compare);if(register)showRegister(register.dataset.register==='group'?'group':'individual');if(e.target.closest('#resetSearch')){$('#programSearch').value='';$('#facultyFilter').value='';limit=6;renderPrograms();}});
 function openModal(html,wide=false){modalContent.innerHTML=html;modal.style.width=wide?'min(1050px,calc(100% - 20px))':'';if(!modal.open){modal.showModal();document.body.style.overflow='hidden';}modal.scrollTop=0;}
 function closeModal(){modal.close();document.body.style.overflow='';}
 $('#closeModal').addEventListener('click',closeModal);modal.addEventListener('close',()=>document.body.style.overflow='');modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
 function showProgram(id){const p=programs().find(p=>p.id===id);if(!p)return;openModal(`<span class="modal-eyebrow">${esc(p.level)} / ${esc(p.faculty)}</span><h2 class="modal-title">${esc(p.name)}</h2><p class="modal-description">Информация о приёме из карточки программы МГТУ.</p><button class="button small outline" data-compare="${esc(p.id)}">${compared.includes(p.id)?'Убрать из сравнения':'Добавить к сравнению'} <span>＋</span></button>${p.image?`<img class="modal-doc" src="${esc(p.image)}" alt="План приёма, вступительные испытания и условия обучения: ${esc(p.name)}"><p class="modal-image-note">Оригинальная карточка программы с исходного сайта МГТУ.</p>`:''}<div class="modal-links"><a href="${esc(p.document||p.image)}" target="_blank" rel="noopener">Подробнее о программе</a><a href="${esc(p.cost||'https://mkgtu.ru/sveden/paid_edu/')}" target="_blank" rel="noopener">Информация о стоимости</a></div><div class="modal-links"><button class="button lime small" data-register>Познакомиться с МГТУ </button></div>`);}
 function toggleCompare(id){if(compared.includes(id))compared=compared.filter(x=>x!==id);else if(compared.length<3)compared.push(id);else return toast('Можно сравнить до трёх направлений. Уберите одно, чтобы добавить новое.');MGTU_write('mgtu-compared',compared);renderPrograms();if(modal.open&&$('#comparisonTable'))showComparison();else if(modal.open){const b=modalContent.querySelector('[data-compare]');if(b){b.innerHTML=`${compared.includes(b.dataset.compare)?'Убрать из сравнения':'Добавить к сравнению'} <span>＋</span>`;}}}
 function syncCompare(){compared=compared.filter(id=>programs().some(p=>p.id===id));$('#compareBar').hidden=!compared.length;$('#compareBar>span').innerHTML=`<b id="compareCount">${compared.length}</b> ${plural(compared.length,'направление','направления','направлений')} в сравнении`;}
 function showComparison(){const list=compared.map(id=>programs().find(p=>p.id===id)).filter(Boolean);if(!list.length){closeModal();return;}openModal(`<span class="modal-eyebrow">ТВОЙ ВЫБОР / ${list.length} ИЗ 3</span><h2 class="modal-title">Сравни. Почувствуй разницу.</h2><p class="modal-description">Сопоставь направления и открой условия приёма каждой программы.</p><div class="compare-table-wrap" id="comparisonTable"><table class="compare-table"><thead><tr><th>Направление</th>${list.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody><tr><td>Уровень</td>${list.map(p=>`<td>${esc(p.level)}</td>`).join('')}</tr><tr><td>Факультет</td>${list.map(p=>`<td>${esc(p.faculty)}</td>`).join('')}</tr><tr><td>Экзамены<br>и места</td>${list.map(p=>`<td><a href="${esc(p.image)}" target="_blank" rel="noopener">Карточка приёма</a></td>`).join('')}</tr><tr><td>Программа</td>${list.map(p=>`<td><a href="${esc(p.document||p.image)}" target="_blank" rel="noopener">Подробнее</a></td>`).join('')}</tr><tr><td>Стоимость</td>${list.map(p=>`<td><a href="${esc(p.cost)}" target="_blank" rel="noopener">Официальная информация</a></td>`).join('')}</tr><tr><td></td>${list.map(p=>`<td><button data-compare="${esc(p.id)}">Убрать из сравнения ×</button></td>`).join('')}</tr></tbody></table></div><div class="modal-links"><button class="button lime small" data-register>Хочу узнать больше на встрече </button></div>`,true);}
 $('#openCompare').addEventListener('click',showComparison);$('#clearCompare').addEventListener('click',()=>{compared=[];MGTU_write('mgtu-compared',compared);renderPrograms();toast('Сравнение очищено');});
 function renderChecklist(){$('#checklist').innerHTML=content.checklist.map((text,i)=>`<label class="check-item"><input type="checkbox" data-check="${i}" ${checked.includes(i)?'checked':''}><span>${esc(text)}</span></label>`).join('');const n=checked.filter(i=>i>=0&&i<content.checklist.length).length;$('#checkCount').textContent=`${n} / ${content.checklist.length}`;$('#checkProgress').style.width=`${n/content.checklist.length*100}%`;}
 $('#checklist').addEventListener('change',e=>{if(!e.target.matches('[data-check]'))return;const i=Number(e.target.dataset.check);checked=e.target.checked?[...new Set([...checked,i])]:checked.filter(x=>x!==i);MGTU_write('mgtu-checklist',checked);renderChecklist();if(checked.length===content.checklist.length)toast('Все шаги отмечены. Ты готов к знакомству с МГТУ!');});

 function initializeTicker(){
  const ticker=$('.ticker'),track=$('.ticker-track');
  const pool=['ОТКРЫВАЙ МГТУ','ПРОБУЙ НОВОЕ','НАХОДИ СВОИХ','ПРИХОДИ С ДРУЗЬЯМИ','ВЫБИРАЙ НАПРАВЛЕНИЕ','СПРАШИВАЙ ОБ УЧЁБЕ','ЗНАКОМЬСЯ С УНИВЕРСИТЕТОМ','СРАВНИВАЙ ПРОГРАММЫ','ПЛАНИРУЙ ПОСТУПЛЕНИЕ','УЗНАЙ БОЛЬШЕ О МГТУ','ЗАГЛЯНИ В ЛАБОРАТОРИИ','ЗАДАВАЙ ВОПРОСЫ','ПРИСМОТРИСЬ К ПРОФЕССИИ','ПОСМОТРИ, КАК МЫ УЧИМСЯ'];
  const shuffled=[...pool];for(let i=shuffled.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[shuffled[i],shuffled[j]]=[shuffled[j],shuffled[i]];}
  const phrases=shuffled.slice(0,6),previous=MGTU_read('mgtu-ticker-phrases',[]);
  if([...phrases].sort().join('|')===[...previous].sort().join('|'))phrases[0]=pool.find(p=>!phrases.includes(p));
  MGTU_write('mgtu-ticker-phrases',phrases);
  const unit=phrases.map(p=>'<span>'+esc(p)+'</span><i aria-hidden="true">✳</i>').join('');
  let lastWidth=0;
  function draw(){lastWidth=ticker.clientWidth;const first=document.createElement('div');first.className='ticker-group';first.innerHTML=unit;track.replaceChildren(first);const unitWidth=Math.max(1,first.getBoundingClientRect().width);first.innerHTML=unit.repeat(Math.max(1,Math.ceil(lastWidth/unitWidth)));track.append(first.cloneNode(true));track.style.setProperty('--ticker-duration',Math.max(15,first.getBoundingClientRect().width/65)+'s');}
  draw();if(document.fonts)document.fonts.ready.then(draw);
  new ResizeObserver(()=>{if(ticker.clientWidth!==lastWidth)draw();}).observe(ticker);
 }
 initializeTicker();
 $('#allFacts').addEventListener('click',()=>openModal(`<span class="modal-eyebrow">МГТУ / БОЛЬШЕ ВОЗМОЖНОСТЕЙ</span><h2 class="modal-title">Университет в деталях</h2><p class="modal-description">Сведения об университете с сайта дня открытых дверей.</p><div class="fact-list">${(content.facts||data.facts).map(f=>`<p>${esc(f)}</p>`).join('')}</div>`,true));
 function showRegister(mode='individual'){
  const group=mode==='group';openModal(`<span class="modal-eyebrow">ДЕНЬ ОТКРЫТЫХ ДВЕРЕЙ / МГТУ</span><h2 class="modal-title">Запись на день<br>открытых дверей</h2><p class="modal-description">${esc(content.date)} · ${esc(content.place)}</p><div class="segmented register-tabs"><button class="${!group?'active':''}" data-reg-mode="individual">Личное участие</button><button class="${group?'active':''}" data-reg-mode="group">Групповое участие</button></div><form id="registrationForm"><div class="form-grid"><label>${group?'Контактное лицо':'Как тебя зовут?'}<input name="name" autocomplete="name" placeholder="Имя и фамилия" required minlength="2" maxlength="100"></label><label>${group?'Твоя роль':'Кто ты?'}<select name="role">${(group?['Учитель / классный руководитель','Представитель школы']:['Абитуриент · 11 класс','Абитуриент · 9 класс','Выпускник СПО','Поступающий в магистратуру','Родитель','Другой гость']).map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Телефон<input name="phone" type="tel" autocomplete="tel" placeholder="+7 (___) ___-__-__" required inputmode="tel" minlength="10" maxlength="22" title="Введите номер телефона: от 10 до 22 символов"></label><label>Электронная почта<input name="email" type="email" autocomplete="email" placeholder="you@example.ru" required maxlength="150"></label>${group?'<label>Школа / организация<input name="school" placeholder="Название организации" required maxlength="200"></label><label>Количество участников<input name="count" type="number" placeholder="Например, 25" min="2" max="500" required></label>':`<label class="full">Что тебе интересно? <select name="interest"><option value="">Пока выбираю</option>${programs().map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.level)}</option>`).join('')}</select></label>`}</div><label class="consent"><input type="checkbox" required><span>Понимаю, что это демонстрация регистрации. Заявка не будет отправлена.</span></label><button class="button lime" type="submit">Посмотреть подтверждение </button><p class="demo-note">Интерактивный макет: данные из формы не сохраняются и не отправляются. На рабочем сайте здесь будет регистрация с уведомлением ответственного.</p><div class="modal-links"><a href="${group?'https://forms.yandex.ru/u/68e4eaf6e010db446163a2fd':'https://forms.yandex.ru/u/69ef26a7e010db001b9370cb'}" target="_blank" rel="noopener">Действующая форма на исходном сайте</a></div></form>`);
  $$('[data-reg-mode]').forEach(b=>b.addEventListener('click',()=>showRegister(b.dataset.regMode)));
  $('#registrationForm').addEventListener('input',e=>{if(e.target.name==='phone')e.target.setCustomValidity('');});
  $('#registrationForm').addEventListener('submit',e=>{e.preventDefault();const phone=e.target.elements.phone;const digits=phone.value.replace(/\D/g,'');phone.setCustomValidity(/^[+\d()\s-]+$/.test(phone.value)&&digits.length>=10&&digits.length<=15?'':'Введите номер телефона: от 10 до 15 цифр.');if(!e.target.reportValidity())return;openModal(`<div class="success-state"><span class="success-icon">✓</span><span class="modal-eyebrow">ПРЕДПРОСМОТР ПОДТВЕРЖДЕНИЯ</span><h2>До встречи<br>в МГТУ!</h2><p>Так будет выглядеть подтверждение после регистрации. В этом макете заявка не отправлена, а контактные данные не сохранены.</p><button class="button dark-button" id="backToPlan">Вернуться к моему плану </button></div>`);$('#backToPlan').addEventListener('click',()=>{closeModal();$('#plan').scrollIntoView({behavior:motion?'smooth':'instant'});});});
 }
 fetch('data.json').then(r=>{if(!r.ok)throw Error('Не удалось загрузить каталог');return r.text();}).then(text=>{data=JSON.parse(text.replace(/^\uFEFF/,''));fillFaculties();renderPrograms();}).catch(()=>{$('#programGrid').innerHTML='<div class="empty-state"><h3>Каталог временно недоступен</h3><p>Откройте программы на официальном сайте МГТУ.</p><a class="button dark-button" href="https://2504.mkgtu.ru/#menu" target="_blank" rel="noopener">Открыть каталог</a></div>';$('#showMore').hidden=true;});
})();
